import{Z as t,e as i,f as o,a0 as n}from"./chunks/framework.DmpHOl9T.js";const h=JSON.parse('{"title":"Payment Field with Stripe — Full Flow","description":"","frontmatter":{},"headers":[],"relativePath":"guides/fields/payment-field-with-stripe-full-flow.md","filePath":"guides/fields/payment-field-with-stripe-full-flow.md","lastUpdated":1782532814000}'),r={name:"guides/fields/payment-field-with-stripe-full-flow.md"};function a(s,e,l,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="payment-field-with-stripe-—-full-flow" tabindex="-1">Payment Field with Stripe — Full Flow <a class="header-anchor" href="#payment-field-with-stripe-—-full-flow" aria-label="Permalink to &quot;Payment Field with Stripe — Full Flow&quot;">​</a></h1><p>This walkthrough connects Stripe to a Formie form end to end: <a href="/integrations/payments/stripe">Stripe integration setup</a>, <a href="/fields/payment">Payment field configuration</a>, form behaviour, and optional subscription features.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A Stripe account with API keys</li><li>A Formie form that will collect payment</li><li><strong>Ajax (Client-side)</strong> submission method on the form (required for Stripe)</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Stripe setup happens in two places:</p><ol><li><strong>Formie → Settings → Payments</strong> — create and connect the Stripe integration.</li><li><strong>Form builder</strong> — add a Payment field and choose Stripe as the provider.</li></ol><p>Payment runs through Formie&#39;s <a href="/guides/submissions-workflows/submission-workflow-and-stages-explained">submission workflow</a>: the submission is validated and screened, payment is authorised or captured during the <strong>save</strong> stage, and notifications and integrations dispatch only after payment succeeds (for charge-at-submit flows).</p><h2 id="step-1-create-the-stripe-integration" tabindex="-1">Step 1: Create the Stripe Integration <a class="header-anchor" href="#step-1-create-the-stripe-integration" aria-label="Permalink to &quot;Step 1: Create the Stripe Integration&quot;">​</a></h2><ol><li>Go to <strong>Formie → Settings → Payments</strong>.</li><li>Click <strong>New Integration</strong>.</li><li>Select <strong>Stripe</strong> as the provider.</li><li>In the <a href="https://dashboard.stripe.com/apikeys" target="_blank" rel="noreferrer">Stripe Dashboard → API Keys</a>, copy the <strong>Publishable Key</strong> and <strong>Secret Key</strong>.</li><li>Paste them into Formie. Store keys in <code>.env</code> variables and reference them in the integration settings — do not commit secrets to project config.</li><li>Save and click <strong>Refresh</strong> in the sidebar to test the connection.</li></ol><p>Use Stripe <strong>Test Mode</strong> keys while developing; switch to live keys before production.</p><h2 id="step-2-configure-webhooks-subscriptions" tabindex="-1">Step 2: Configure Webhooks (Subscriptions) <a class="header-anchor" href="#step-2-configure-webhooks-subscriptions" aria-label="Permalink to &quot;Step 2: Configure Webhooks (Subscriptions)&quot;">​</a></h2><p>Webhooks are required for subscription payments and recommended for reliable status updates.</p><ol><li>In Stripe, open <strong>Developers → Webhooks</strong>.</li><li>Click <strong>Create an event destination</strong>.</li><li>Copy the <strong>Redirect URI</strong> from Formie integration settings into Stripe&#39;s <strong>Endpoint URL</strong>.</li><li>Select events — at minimum: <ul><li><code>customer.subscription.created</code></li><li><code>customer.subscription.deleted</code></li><li><code>customer.subscription.updated</code></li><li><code>invoice.created</code></li><li><code>invoice.payment_failed</code></li><li><code>invoice.payment_succeeded</code></li><li><code>payment_intent.succeeded</code></li><li><code>payment_intent.payment_failed</code></li><li><code>payment_intent.canceled</code></li><li><code>plan.deleted</code></li><li><code>plan.updated</code></li></ul></li><li>Copy the <strong>Signing secret</strong> into Formie&#39;s <strong>Webhook Signing Secret</strong> field.</li></ol><h2 id="step-3-add-a-payment-field" tabindex="-1">Step 3: Add a Payment Field <a class="header-anchor" href="#step-3-add-a-payment-field" aria-label="Permalink to &quot;Step 3: Add a Payment Field&quot;">​</a></h2><ol><li>Edit your form.</li><li>Set <strong>Submission Method</strong> to <strong>Ajax (Client-side)</strong>. Stripe tokenisation requires Formie&#39;s client submission flow.</li><li>Add a <strong>Payment</strong> field.</li><li>Select your Stripe integration for <strong>Payment Integration</strong>.</li><li>Configure <strong>Amount</strong> — fixed value, dynamic value from another field, or use <a href="/fields/calculations">Calculations</a> to derive the amount.</li><li>Map <strong>Billing details</strong> — name, email, address fields — to Stripe&#39;s expected customer data.</li></ol><p>Save the form and preview on the front end. Stripe Elements (or the configured hosted UI) should render inside the Payment field.</p><h2 id="step-4-submit-and-verify" tabindex="-1">Step 4: Submit and Verify <a class="header-anchor" href="#step-4-submit-and-verify" aria-label="Permalink to &quot;Step 4: Submit and Verify&quot;">​</a></h2><ol><li>Submit a test payment using Stripe test card <code>4242 4242 4242 4242</code>.</li><li>Confirm the submission appears in <strong>Formie → Submissions</strong> with payment metadata.</li><li>Check that email notifications and integrations fired after successful payment.</li></ol><p>Failed payments should surface as submission errors on the form without creating a completed paid submission.</p><h2 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to &quot;Subscriptions&quot;">​</a></h2><p>For recurring payments:</p><ol><li>Edit the Payment field and set <strong>Payment Type</strong> to <strong>Subscription</strong>.</li><li>Configure the recurring amount and interval per Stripe integration settings.</li></ol><h3 id="payment-limits" tabindex="-1">Payment Limits <a class="header-anchor" href="#payment-limits" aria-label="Permalink to &quot;Payment Limits&quot;">​</a></h3><p>Limit how many billing cycles Stripe collects before auto-cancelling:</p><ol><li>Under <strong>Payment Limit</strong>, choose <strong>Fixed Value</strong> or <strong>Dynamic Value</strong>.</li><li>Enter a count (for example <code>3</code> for three instalments) or select a Number field.</li></ol><p>Formie creates the subscription through a Stripe subscription schedule. Leave <strong>No limit</strong> for ongoing subscriptions.</p><h3 id="setup-fees" tabindex="-1">Setup Fees <a class="header-anchor" href="#setup-fees" aria-label="Permalink to &quot;Setup Fees&quot;">​</a></h3><p>Charge a one-time fee on the first invoice:</p><ol><li>Under <strong>Setup Fee</strong>, choose <strong>Fixed Value</strong> or <strong>Dynamic Value</strong>.</li><li>Optionally set <strong>Setup Fee Description</strong> for the Stripe invoice line item.</li></ol><p>Setup fees use Stripe <code>add_invoice_items</code> on the first subscription invoice.</p><p>Modify subscription payloads with the <code>modifySubscriptionPayload</code> and <code>modifySubscriptionSchedulePayload</code> events if your project needs custom Stripe parameters.</p><h2 id="dynamic-amounts-with-calculations" tabindex="-1">Dynamic Amounts with Calculations <a class="header-anchor" href="#dynamic-amounts-with-calculations" aria-label="Permalink to &quot;Dynamic Amounts with Calculations&quot;">​</a></h2><p>When the payment amount depends on other fields:</p><ol><li>Add Number or Dropdown fields for the inputs.</li><li>Add a <strong>Calculations</strong> field for the total.</li><li>On the Payment field, set amount source to the Calculations field (dynamic value).</li></ol><p>The Calculations field updates on the front end as inputs change; the Payment field reads the computed value at submit time.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Stripe UI does not appear</td><td>Form must use Ajax submission; confirm publishable key and front-end assets load</td></tr><tr><td>Payment succeeds but no submission</td><td>Webhook/callback configuration; check Craft logs for payment replay errors</td></tr><tr><td>Integration refresh fails</td><td>Secret key, API mode (test vs live), server outbound HTTPS</td></tr><tr><td>Subscriptions stuck pending</td><td>Webhook signing secret and required subscription events</td></tr></tbody></table>',38)])])}const m=t(r,[["render",a]]);export{h as __pageData,m as default};
